#include <algorithm>
#include <array>
#include <atomic>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstring>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <limits>
#include <numeric>
#include <random>
#include <stdexcept>
#include <string>
#include <thread>
#include <vector>

constexpr int NF=9;
struct Dataset{uint32_t samples{},features{},classes{},groups{};std::vector<float>pairs,x;std::vector<int32_t>y,group;};
template<class T>void readv(std::ifstream&f,std::vector<T>&v,size_t n){v.resize(n);f.read(reinterpret_cast<char*>(v.data()),n*sizeof(T));if(!f)throw std::runtime_error("truncated dataset");}
Dataset load(const std::string&p){std::ifstream f(p,std::ios::binary);if(!f)throw std::runtime_error("cannot open "+p);char m[8];f.read(m,8);if(std::string(m,8)!="HSIRL001")throw std::runtime_error("wrong dataset format");Dataset d;f.read(reinterpret_cast<char*>(&d.samples),4);f.read(reinterpret_cast<char*>(&d.features),4);f.read(reinterpret_cast<char*>(&d.classes),4);f.read(reinterpret_cast<char*>(&d.groups),4);readv(f,d.pairs,d.features*2);readv(f,d.y,d.samples);readv(f,d.group,d.samples);readv(f,d.x,size_t(d.samples)*d.features);return d;}

std::vector<int> folds_for(const Dataset&d,int folds,uint32_t seed){std::vector<int>gc(d.groups,-1),ga(d.groups,-1),sf(d.samples);for(uint32_t s=0;s<d.samples;++s)gc[d.group[s]]=d.y[s];std::mt19937 rng(seed);for(uint32_t c=0;c<d.classes;++c){std::vector<int>ids;for(uint32_t g=0;g<d.groups;++g)if(gc[g]==int(c))ids.push_back(g);if(int(ids.size())<folds)throw std::runtime_error("too many folds");std::shuffle(ids.begin(),ids.end(),rng);for(size_t i=0;i<ids.size();++i)ga[ids[i]]=i%folds;}for(uint32_t s=0;s<d.samples;++s)sf[s]=ga[d.group[s]];return sf;}
struct Fold{std::vector<int>samples;std::vector<float>contrib;};
std::vector<Fold> precompute(const Dataset&d,const std::vector<int>&sf,int nfolds){std::vector<Fold>out(nfolds);for(int fold=0;fold<nfolds;++fold){auto&o=out[fold];for(uint32_t s=0;s<d.samples;++s)if(sf[s]==fold)o.samples.push_back(s);size_t stride=o.samples.size()*d.classes;o.contrib.resize(size_t(d.features)*stride);std::vector<double>sum(size_t(d.features)*d.classes),sq(sum.size());std::vector<int>count(d.classes);for(uint32_t s=0;s<d.samples;++s)if(sf[s]!=fold){int c=d.y[s];++count[c];for(uint32_t f=0;f<d.features;++f){double x=d.x[size_t(s)*d.features+f];size_t p=size_t(f)*d.classes+c;sum[p]+=x;sq[p]+=x*x;}}for(uint32_t f=0;f<d.features;++f){double pooled=0;int denom=0;for(uint32_t c=0;c<d.classes;++c){size_t p=size_t(f)*d.classes+c;double mean=sum[p]/count[c];pooled+=sq[p]-count[c]*mean*mean;denom+=count[c]-1;}double var=std::max(pooled/std::max(1,denom),1e-12);for(size_t s=0;s<o.samples.size();++s){float x=d.x[size_t(o.samples[s])*d.features+f];for(uint32_t c=0;c<d.classes;++c){double mean=sum[size_t(f)*d.classes+c]/count[c],delta=x-mean;o.contrib[size_t(f)*stride+s*d.classes+c]=float(delta*delta/var);}}}}return out;}

float score(const Dataset&d,const std::vector<Fold>&folds,const std::vector<uint16_t>&subset){if(subset.empty())return 1.0f/d.classes;float total=0;for(const auto&fold:folds){size_t stride=fold.samples.size()*d.classes;std::vector<int>correct(d.classes),count(d.classes);for(size_t s=0;s<fold.samples.size();++s){int pred=0;float best=0;for(auto f:subset)best+=fold.contrib[size_t(f)*stride+s*d.classes];for(uint32_t c=1;c<d.classes;++c){float dist=0;for(auto f:subset)dist+=fold.contrib[size_t(f)*stride+s*d.classes+c];if(dist<best){best=dist;pred=c;}}int truth=d.y[fold.samples[s]];++count[truth];if(pred==truth)++correct[truth];}float ba=0;for(uint32_t c=0;c<d.classes;++c)ba+=float(correct[c])/count[c];total+=ba/d.classes;}return total/folds.size();}

std::vector<float> correlations(const Dataset&d){std::vector<double>mean(d.features),ss(d.features);for(uint32_t s=0;s<d.samples;++s)for(uint32_t f=0;f<d.features;++f)mean[f]+=d.x[size_t(s)*d.features+f];for(auto&v:mean)v/=d.samples;for(uint32_t s=0;s<d.samples;++s)for(uint32_t f=0;f<d.features;++f){double z=d.x[size_t(s)*d.features+f]-mean[f];ss[f]+=z*z;}std::vector<float>r(size_t(d.features)*d.features);for(uint32_t a=0;a<d.features;++a){r[size_t(a)*d.features+a]=1;for(uint32_t b=a+1;b<d.features;++b){double cross=0;for(uint32_t s=0;s<d.samples;++s)cross+=(d.x[size_t(s)*d.features+a]-mean[a])*(d.x[size_t(s)*d.features+b]-mean[b]);float v=float(std::abs(cross/std::sqrt(std::max(1e-20,ss[a]*ss[b]))));r[size_t(a)*d.features+b]=r[size_t(b)*d.features+a]=v;}}return r;}
float redundancy(const std::vector<float>&corr,uint32_t width,uint16_t candidate,const std::vector<uint16_t>&selected){if(selected.empty())return 0;float v=0;for(auto f:selected)v+=corr[size_t(candidate)*width+f];return v/selected.size();}

struct Policy{int steps;std::vector<std::array<double,NF>>w,m,v;uint64_t updates=0;explicit Policy(int n):steps(n),w(n),m(n),v(n){for(auto&row:w)row={.1,.3,.5,-.05,.1,.1,-.1,0,0};};
 void update(const std::vector<std::array<double,NF>>&grads,double advantage,double lr){++updates;for(int t=0;t<steps;++t)for(int j=0;j<NF;++j){double g=advantage*grads[t][j];m[t][j]=.9*m[t][j]+.1*g;v[t][j]=.999*v[t][j]+.001*g*g;double mh=m[t][j]/(1-std::pow(.9,double(updates))),vh=v[t][j]/(1-std::pow(.999,double(updates)));w[t][j]+=lr*mh/(std::sqrt(vh)+1e-8);}}
};
struct Action{uint16_t id;std::array<double,NF>raw{},z{};double logit{},prob{};};

std::vector<uint16_t> rollout_completion(const Dataset&d,const Policy&policy,const std::vector<float>&individual,const std::vector<float>&corr,std::vector<uint16_t>set,int target,std::mt19937&rng){while(int(set.size())<target){std::vector<uint16_t>ids;std::vector<double>logits;int step=set.size();double maxlog=-1e100;for(uint16_t f=0;f<d.features;++f)if(std::find(set.begin(),set.end(),f)==set.end()){double ex=(d.pairs[2*f]-300)/150.0,em=(d.pairs[2*f+1]-400)/350.0;double l=policy.w[step][0]*individual[f]+policy.w[step][6]*redundancy(corr,d.features,f,set)+policy.w[step][7]*ex+policy.w[step][8]*em;ids.push_back(f);logits.push_back(l);maxlog=std::max(maxlog,l);}double sum=0;for(auto&l:logits){l=std::exp(std::clamp(l-maxlog,-30.0,30.0));sum+=l;}std::uniform_real_distribution<double>u(0,sum);double pick=u(rng);size_t pos=0;for(;pos+1<logits.size()&&pick>logits[pos];++pos)pick-=logits[pos];set.push_back(ids[pos]);}return set;}

std::vector<Action> action_table(const Dataset&d,const std::vector<Fold>&folds,const Policy&policy,const std::vector<float>&individual,const std::vector<float>&corr,const std::vector<uint16_t>&selected,int target,int rollouts,int episode,int step,unsigned threads){float current=score(d,folds,selected);std::vector<Action>a;for(uint16_t f=0;f<d.features;++f)if(std::find(selected.begin(),selected.end(),f)==selected.end())a.push_back({f});std::atomic<size_t>next{0};auto worker=[&]{while(true){size_t i=next.fetch_add(1);if(i>=a.size())break;auto&x=a[i];auto prefix=selected;prefix.push_back(x.id);x.raw[0]=individual[x.id];x.raw[1]=score(d,folds,prefix)-current;double sum=0,sq=0,mn=1e9,mx=-1e9;for(int r=0;r<rollouts;++r){std::mt19937 rng(uint32_t(1469598103u+episode*1000003u+step*10007u+x.id*101u+r));auto complete=rollout_completion(d,policy,individual,corr,prefix,target,rng);double s=score(d,folds,complete);sum+=s;sq+=s*s;mn=std::min(mn,s);mx=std::max(mx,s);}double mean=sum/rollouts;x.raw[2]=mean;x.raw[3]=std::sqrt(std::max(0.0,sq/rollouts-mean*mean));x.raw[4]=mn;x.raw[5]=mx;x.raw[6]=redundancy(corr,d.features,x.id,selected);x.raw[7]=(d.pairs[2*x.id]-300)/150.0;x.raw[8]=(d.pairs[2*x.id+1]-400)/350.0;}};std::vector<std::thread>pool;for(unsigned i=0;i<threads;++i)pool.emplace_back(worker);for(auto&t:pool)t.join();
 for(int j=0;j<NF;++j){double mean=0;for(auto&x:a)mean+=x.raw[j];mean/=a.size();double var=0;for(auto&x:a)var+=(x.raw[j]-mean)*(x.raw[j]-mean);double sd=std::sqrt(var/a.size());for(auto&x:a)x.z[j]=sd<1e-12?0:(x.raw[j]-mean)/sd;}
 double maxlog=-1e100;for(auto&x:a){x.logit=0;for(int j=0;j<NF;++j)x.logit+=policy.w[step][j]*x.z[j];maxlog=std::max(maxlog,x.logit);}double temperature=std::max(.25,1.25*std::pow(.985,episode)),sum=0;for(auto&x:a){x.prob=std::exp(std::clamp((x.logit-maxlog)/temperature,-30.0,30.0));sum+=x.prob;}for(auto&x:a)x.prob/=sum;return a;}

int main(int argc,char**argv)try{if(argc<3){std::cerr<<"Usage: native_mc_rl DATA.bin OUTPUT_DIR [N=13] [EPISODES=30] [ROLLOUTS=3] [THREADS]\n";return 2;}std::string input=argv[1],outdir=argv[2];int target=argc>3?std::stoi(argv[3]):13,episodes=argc>4?std::stoi(argv[4]):30,rollouts=argc>5?std::stoi(argv[5]):3;unsigned threads=argc>6?std::stoul(argv[6]):std::max(1u,std::thread::hardware_concurrency());if(target<1||rollouts<1||episodes<1)throw std::runtime_error("N, episodes and rollouts must be positive");std::filesystem::create_directories(outdir);auto started=std::chrono::steady_clock::now();Dataset d=load(input);if(target>int(d.features))throw std::runtime_error("N exceeds feature count");auto folds=precompute(d,folds_for(d,3,42),3);std::cout<<"Precomputing individual scores and redundancy...\n";std::vector<float>individual(d.features);for(uint16_t f=0;f<d.features;++f)individual[f]=score(d,folds,{f})-1.0f/d.classes;auto corr=correlations(d);Policy policy(target);std::mt19937 rng(42);double baseline=.2;float best=-1;std::vector<uint16_t>best_set;std::ofstream history(outdir+"/episodes.csv");history<<"episode,score,baseline,advantage,selected_indices\n";
 for(int episode=0;episode<episodes;++episode){std::vector<uint16_t>selected;std::vector<std::array<double,NF>>grads(target);for(int step=0;step<target;++step){auto actions=action_table(d,folds,policy,individual,corr,selected,target,rollouts,episode,step,threads);std::uniform_real_distribution<double>u(0,1);double pick=u(rng);size_t chosen=0;for(;chosen+1<actions.size()&&pick>actions[chosen].prob;++chosen)pick-=actions[chosen].prob;std::array<double,NF>expected{};for(const auto&a:actions)for(int j=0;j<NF;++j)expected[j]+=a.prob*a.z[j];for(int j=0;j<NF;++j)grads[step][j]=actions[chosen].z[j]-expected[j];selected.push_back(actions[chosen].id);}float final=score(d,folds,selected);double advantage=final-baseline;policy.update(grads,advantage,.015);baseline=episode==0?final:.9*baseline+.1*final;if(final>best){best=final;best_set=selected;}history<<episode<<','<<final<<','<<baseline<<','<<advantage<<",\"";for(size_t i=0;i<selected.size();++i)history<<(i?" ":"")<<selected[i];history<<"\"\n";std::cout<<"Episode "<<episode+1<<'/'<<episodes<<" score="<<final<<" best="<<best<<" baseline="<<baseline<<'\n';}
 std::vector<uint16_t>greedy;for(int step=0;step<target;++step){auto actions=action_table(d,folds,policy,individual,corr,greedy,target,rollouts,episodes+1000,step,threads);auto chosen=std::max_element(actions.begin(),actions.end(),[](const Action&a,const Action&b){return a.logit<b.logit;});greedy.push_back(chosen->id);}float greedy_score=score(d,folds,greedy);if(greedy_score>best){best=greedy_score;best_set=greedy;}
 std::ofstream result(outdir+"/best_set.csv");result<<"position,index,excitation_nm,emission_nm\n";for(size_t i=0;i<best_set.size();++i){auto f=best_set[i];result<<i+1<<','<<f<<','<<d.pairs[2*f]<<','<<d.pairs[2*f+1]<<'\n';}std::ofstream weights(outdir+"/policy_weights.csv");weights<<"step,individual,marginal,future_mean,future_std,future_min,future_max,redundancy,excitation,emission\n";for(int t=0;t<target;++t){weights<<t+1;for(double w:policy.w[t])weights<<','<<w;weights<<'\n';}double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-started).count();std::ofstream summary(outdir+"/summary.txt");summary<<"algorithm=REINFORCE with policy-guided Monte Carlo rollouts\nselected_count="<<target<<"\nepisodes="<<episodes<<"\nrollouts="<<rollouts<<"\ngreedy_trained_policy_score="<<greedy_score<<"\nbest_balanced_accuracy="<<best<<"\nelapsed_seconds="<<seconds<<"\n";std::cout<<"Trained-policy deterministic score: "<<greedy_score<<"\nBest balanced accuracy: "<<best<<"\nElapsed: "<<seconds<<" seconds\nResults: "<<outdir<<'\n';return 0;}catch(const std::exception&e){std::cerr<<"Error: "<<e.what()<<'\n';return 1;}
